t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

gpairs = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    text = t[m.end():].split('\n')[:1]
    key = m[1]
    if key and text:
        rows = [line.split() for line in text if line.strip() and key.replace(' ', '').isdigit() in key or key.lower().startswith('demo') or key in ('Test input',)]
        if 'input' in key.lower():
            gpairs[key] = [[int(x) for x in row] for row in rows]

# Better regex for grids
all_grids = {}
